import bisect

TOMBSTONE = object()  # a delete is a write of this marker

class TinyLSM:  # toy: no WAL, no Bloom filters, one flat list of runs
    def __init__(self, memtable_limit: int = 4):
        self.memtable, self.runs, self.limit = {}, [], memtable_limit  # runs: oldest first

    def put(self, key, value):
        self.memtable[key] = value  # real engines append to a WAL first
        if len(self.memtable) >= self.limit:
            self.runs.append(sorted(self.memtable.items()))  # flush: one sequential write
            self.memtable = {}

    def delete(self, key):
        self.put(key, TOMBSTONE)

    def get(self, key):
        if key in self.memtable:
            v = self.memtable[key]
            return None if v is TOMBSTONE else v
        for run in reversed(self.runs):  # newest first; each probe is read amplification
            i = bisect.bisect_left(run, (key,))
            if i < len(run) and run[i][0] == key:
                v = run[i][1]
                return None if v is TOMBSTONE else v
        return None

    def compact(self):
        merged = {}
        for run in self.runs:  # oldest first, so newer values overwrite older ones
            merged.update(run)
        # Dropping tombstones is safe only because every run is merged
        self.runs = [sorted((k, v) for k, v in merged.items() if v is not TOMBSTONE)]
